#!/usr/bin/env python3
from pwn import *

def analyze_section(data):
    # Look for validation patterns
    validation_patterns = {
        'length_check': b'\x48\x83\xf8',    # cmp rax, imm8
        'char_check': b'\x3c',              # cmp al, imm8
        'jump_if': b'\x0f\x84',             # je rel32
        'jump_not': b'\x0f\x85',            # jne rel32
        'buffer_copy': b'\xf3\xa4',         # rep movsb
        'string_load': b'\x48\x8d\x35'      # lea rsi, [rip + disp32]
    }

    findings = []
    for name, pattern in validation_patterns.items():
        positions = []
        pos = 0
        while True:
            pos = data.find(pattern, pos)
            if pos == -1:
                break
            positions.append(pos)
            pos += 1
        if positions:
            findings.append(f"{name}: found at offsets {[hex(p) for p in positions]}")

    # Look for ASCII strings
    strings = []
    current = ''
    for i, b in enumerate(data):
        if 32 <= b <= 126:
            current += chr(b)
        elif current and len(current) >= 4:  # Only collect strings of 4+ chars
            strings.append((i - len(current), current))
            current = ''
        else:
            current = ''

    if strings:
        findings.append("\nPotential strings:")
        for offset, s in strings:
            findings.append(f"{hex(offset)}: {s}")

    return findings

def main():
    with open("chal/cell.pkg", 'rb') as f:
        data = f.read()

    sections = {
        0x645f: "Input Processing",
        0x10ad3: "Validation Logic",
        0x23b23: "Error Handling"
    }

    for offset, name in sections.items():
        print(f"\n=== Analysis of {name} at {hex(offset)} ===")
        section_data = data[offset:offset+0x400]
        findings = analyze_section(section_data)
        for finding in findings:
            print(finding)

if __name__ == '__main__':
    main()

