#!/usr/bin/env python3
from pwn import *
import string
import collections

def analyze_patterns(data):
    # Count byte frequency
    freq = collections.Counter(data)

    # Check for repeating sequences
    sequences = []
    for i in range(len(data)-3):
        seq = data[i:i+4]
        if data.count(seq) > 1 and seq not in sequences:
            sequences.append(seq)

    # Look for potential xor keys
    potential_keys = []
    for i in range(256):
        decoded = bytes([b ^ i for b in data])
        if all(chr(b) in string.printable for b in decoded[:10]):
            potential_keys.append(i)

    # Check for cell-like patterns - look for sequences of 8 bytes
    cell_patterns = []
    for i in range(len(data)-7):
        window = data[i:i+8]
        # Check if window could be cell coordinates
        if all(32 <= b <= 126 for b in window):
            cell_patterns.append(window)

    return {
        'frequency': freq,
        'repeating_sequences': sequences[:5],  # Limit to top 5
        'potential_xor_keys': potential_keys,
        'cell_patterns': cell_patterns
    }

def main():
    sections = {}

    # Read each extracted section
    for offset in [0x645f, 0x10ad3, 0x23b23]:
        try:
            with open(f"section_{offset:x}.bin", "rb") as f:
                sections[offset] = f.read()
        except FileNotFoundError:
            print(f"Couldn't find section_{offset:x}.bin")
            continue

    # Analyze each section
    for offset, data in sections.items():
        print(f"\nAnalyzing section 0x{offset:x}")
        analysis = analyze_patterns(data)

        print("\nTop 10 byte frequencies:")
        for byte, count in analysis['frequency'].most_common(10):
            try:
                char = chr(byte) if 32 <= byte <= 126 else '.'
                print(f"0x{byte:02x} ({char}): {count}")
            except:
                print(f"0x{byte:02x}: {count}")

        print("\nRepeating sequences:")
        for seq in analysis['repeating_sequences']:
            print(f"Sequence: {seq.hex()} (ASCII: {seq})")

        print("\nPotential XOR keys:")
        print(analysis['potential_xor_keys'])

        print("\nPotential cell patterns:")
        for pattern in analysis['cell_patterns'][:5]:  # Show only first 5
            print(f"Pattern: {pattern}")

if __name__ == "__main__":
    main()

