from pwn import *
import base64
import string
import re

def xor_bytes(data, keys):
    if isinstance(keys, int):
        return bytes([b ^ keys for b in data])
    else:
        result = bytearray()
        for i, b in enumerate(data):
            result.append(b ^ keys[i % len(keys)])
        return bytes(result)

def try_base64_decode(data):
    try:
        # Try with padding variations
        for padding in ['', '=', '==', '===']:
            try:
                return base64.b64decode(data + padding.encode())
            except:
                continue
        return None
    except:
        return None

def analyze_data(data, desc=""):
    # Look for readable strings and flag pattern
    try:
        decoded = data.decode('utf-8', errors='ignore')
        if 'csaw_ctf{' in decoded:
            print(f"\nPossible flag found in {desc}!")
            print(decoded)
        elif any(x in decoded for x in ['flag', 'csaw', 'ctf']):
            print(f"\nInteresting string found in {desc}:")
            print(decoded[:200])
    except:
        pass

# Read the binary file
with open('/home/ctfplayer/ctf_files/chal/cell.pkg', 'rb') as f:
    pkg_data = f.read()

# Start at offset 0x645f
start_offset = 0x645f
data_to_decrypt = pkg_data[start_offset:start_offset + 1024]  # Look at first 1KB

print("Starting decryption analysis...")

# Single key XOR
single_keys = [0x1e, 0x78, 0x48]
for key in single_keys:
    decrypted = xor_bytes(data_to_decrypt, key)
    analyze_data(decrypted, f"XOR with 0x{key:02x}")

    # Try base64 on XORed data
    b64_decoded = try_base64_decode(decrypted)
    if b64_decoded:
        analyze_data(b64_decoded, f"Base64 decode after XOR 0x{key:02x}")

# Combined key XOR
combined_keys = [
    bytes([0x1e, 0x78]),
    bytes([0x78, 0x48]),
    bytes([0x1e, 0x48]),
    bytes([0x1e, 0x78, 0x48])
]

for keys in combined_keys:
    decrypted = xor_bytes(data_to_decrypt, keys)
    analyze_data(decrypted, f"XOR with keys {[hex(k) for k in keys]}")

    # Try base64 on XORed data
    b64_decoded = try_base64_decode(decrypted)
    if b64_decoded:
        analyze_data(b64_decoded, f"Base64 decode after XOR {[hex(k) for k in keys]}")

# Try extracting potential base64 chunks
print("\nAnalyzing potential base64 chunks...")
for i in range(0, len(data_to_decrypt)-32, 8):
    chunk = data_to_decrypt[i:i+64]
    decoded = try_base64_decode(chunk)
    if decoded:
        analyze_data(decoded, f"Base64 chunk at offset +{i:x}")

print("\nHexdump of data section:")
print(hexdump(data_to_decrypt))
